@php($payload=$trackingPayload)
@php($money=fn($n)=>app(\App\Support\StorefrontCurrencyContext::class)->formatSnapshot($n,$payload['currency'],$payload['currencyExchangeRate']??1))
<header class="hd-tracking-result-heading"><p>Order {{ $payload['number'] }}</p><h1>Your home, taking shape.</h1><p>Follow the latest updates for your order.</p></header>
<div class="hd-information-grid"><section><small>Order status</small><h3>{{ $payload['statusLabel'] }}</h3></section><section><small>Tracking number</small><h3>{{ $payload['tracking']['number']?:'Not available yet' }}</h3>@if($payload['tracking']['number'])<button class="hd-link" x-data="{copied:false}" @click="navigator.clipboard.writeText(@js($payload['tracking']['number']));copied=true" x-text="copied?'Copied':'Copy tracking number'">Copy tracking number</button>@endif</section><section><small>Courier</small><h3>{{ $payload['tracking']['carrier']?:'Not available yet' }}</h3></section></div>
<section class="hd-tracking-updates"><h2>Latest update</h2>@foreach($payload['timeline'] as $event)<article><h3>{{ $event['title'] }}</h3>@if($event['timestamp'])<time>{{ \Carbon\Carbon::parse($event['timestamp'])->format('d M Y') }}</time>@endif<p>{{ $event['description'] }}</p>@if($event['location'])<small>{{ $event['location'] }}</small>@endif</article>@endforeach</section>
<section class="hd-selected"><h2>Ordered pieces</h2><div class="hd-object-grid">@foreach($payload['items'] as $item)<article class="hd-object-card">@if($item['imageUrl'])<img src="{{ $item['imageUrl'] }}" alt="{{ $item['title'] }}">@endif<div><h3>{{ $item['title'] }}</h3><p>{{ $item['variantTitle'] }}</p><p>Qty {{ $item['quantity'] }}</p><strong>{{ $money($item['lineTotal']) }}</strong></div></article>@endforeach</div></section>
<div class="hd-information-grid hd-two"><section><h2>Shipping to</h2>@if($payload['address']??null)<address>{{ $payload['address']['line1'] }}<br>{{ $payload['address']['city'] }} {{ $payload['address']['postalCode'] }}</address>@endif</section><section><h2>Order summary</h2><dl>@foreach(['subtotal'=>'Subtotal','discount'=>'Discount','shipping'=>'Shipping','tax'=>'Tax','total'=>'Total'] as $key=>$label)@if(in_array($key,['subtotal','shipping','total'])||($payload['totals'][$key]??0))<div><dt>{{ $label }}</dt><dd>{{ $money($payload['totals'][$key]??0) }}</dd></div>@endif@endforeach</dl></section></div>
